def find_nth_good_integer(N: int) -> int:
    digits = [0, 2, 4, 6, 8]
    count = 0
    current_number = 0

    while True:
        current_number += 1
        str_number = str(current_number)
        if all(int(digit) in digits for digit in str_number):
            count += 1
            if count == N:
                return current_number
